package sdkgen

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"go/format"
	"sort"
	"strings"
)

// Manifest records generator ownership of every generated file. It is written
// last and never lists itself, so it cannot claim its own digest.
type Manifest struct {
	GeneratorVersion string          `json:"generatorVersion"`
	TemplateVersion  string          `json:"templateVersion"`
	SpecDigest       string          `json:"specDigest"`
	PackageName      string          `json:"packageName"`
	ModulePath       string          `json:"modulePath"`
	Files            []ManifestEntry `json:"files"`
}

// ManifestEntry is one owned file.
type ManifestEntry struct {
	Path   string `json:"path"`
	Digest string `json:"digest"`
	Kind   string `json:"kind"`
}

func digestBytes(b []byte) string {
	sum := sha256.Sum256(b)
	return hex.EncodeToString(sum[:])
}

// buildFiles renders every generated file and the ownership manifest.
func buildFiles(doc *specDoc, opts Options, ops []Operation, unsupported []UnsupportedOperation, diags []Diagnostic, specDigest string) ([]File, Manifest, error) {
	var files []File

	clientSrc, err := formatGo("client.go", renderClient(opts, doc, specDigest))
	if err != nil {
		return nil, Manifest{}, err
	}
	files = append(files, File{RelPath: "client.go", Content: clientSrc, Digest: digestBytes(clientSrc), Kind: "source"})

	if len(ops) > 0 {
		opsSrc, err := formatGo("operations.go", renderOperations(opts, ops))
		if err != nil {
			return nil, Manifest{}, err
		}
		files = append(files, File{RelPath: "operations.go", Content: opsSrc, Digest: digestBytes(opsSrc), Kind: "source"})
	}

	readme := []byte(renderReadme(opts, doc, ops, unsupported, diags))
	files = append(files, File{RelPath: "README.md", Content: readme, Digest: digestBytes(readme), Kind: "readme"})

	gomod := []byte("module " + opts.ModulePath + "\n\ngo 1.21\n")
	files = append(files, File{RelPath: "go.mod", Content: gomod, Digest: digestBytes(gomod), Kind: "module"})

	sort.Slice(files, func(i, j int) bool { return files[i].RelPath < files[j].RelPath })

	manifest := Manifest{
		GeneratorVersion: GeneratorVersion,
		TemplateVersion:  TemplateVersion,
		SpecDigest:       specDigest,
		PackageName:      opts.PackageName,
		ModulePath:       opts.ModulePath,
		Files:            make([]ManifestEntry, 0, len(files)),
	}
	for _, f := range files {
		manifest.Files = append(manifest.Files, ManifestEntry{Path: f.RelPath, Digest: f.Digest, Kind: f.Kind})
	}
	manifestBytes, err := marshalManifest(manifest)
	if err != nil {
		return nil, Manifest{}, err
	}
	files = append(files, File{
		RelPath: ManifestName,
		Content: manifestBytes,
		Digest:  digestBytes(manifestBytes),
		Kind:    "manifest",
	})
	sort.Slice(files, func(i, j int) bool { return files[i].RelPath < files[j].RelPath })
	return files, manifest, nil
}

func marshalManifest(m Manifest) ([]byte, error) {
	b, err := json.MarshalIndent(m, "", "  ")
	if err != nil {
		return nil, fmt.Errorf("sdkgen: encode manifest: %w", err)
	}
	return append(b, '\n'), nil
}

// formatGo formats generated source with go/format so output is canonical.
func formatGo(name, src string) ([]byte, error) {
	out, err := format.Source([]byte(src))
	if err != nil {
		return nil, fmt.Errorf("sdkgen: format %s: %w", name, err)
	}
	return out, nil
}

const clientTemplate = `// Code generated by GoRequest sdkgen; DO NOT EDIT.
// generator: ` + GeneratorVersion + `
// template: ` + TemplateVersion + `
// spec-sha256: {{DIGEST}}

// Package {{PKG}} is a Go HTTP client generated from an OpenAPI {{VERSION}} contract.
//
// The client uses only the Go standard library. Callers supply the base URL and
// any authentication through Client.Auth; no credentials are embedded.
package {{PKG}}

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strings"
	"time"
)

const (
	// DefaultTimeout bounds a request when no custom http.Client is supplied.
	DefaultTimeout = 30 * time.Second
	// DefaultMaxResponseBytes bounds how much of a response body is read.
	DefaultMaxResponseBytes int64 = 8 << 20
)

// Client is a generated HTTP client. BaseURL is required. HTTPClient defaults to
// a client with DefaultTimeout. Auth, when set, runs before every request and
// may add credentials; the generated code never embeds them.
type Client struct {
	BaseURL          string
	HTTPClient       *http.Client
	Auth             func(*http.Request) error
	UserAgent        string
	MaxResponseBytes int64
}

// Option configures a Client.
type Option func(*Client)

// WithHTTPClient uses h for requests. A nil h is ignored.
func WithHTTPClient(h *http.Client) Option {
	return func(c *Client) {
		if h != nil {
			c.HTTPClient = h
		}
	}
}

// WithAuth installs a hook that adds authentication to each request.
func WithAuth(fn func(*http.Request) error) Option {
	return func(c *Client) { c.Auth = fn }
}

// WithUserAgent sets the User-Agent header sent with each request.
func WithUserAgent(ua string) Option {
	return func(c *Client) { c.UserAgent = ua }
}

// WithMaxResponseBytes bounds the response body read; n <= 0 keeps the default.
func WithMaxResponseBytes(n int64) Option {
	return func(c *Client) {
		if n > 0 {
			c.MaxResponseBytes = n
		}
	}
}

// NewClient validates baseURL and returns a Client.
func NewClient(baseURL string, opts ...Option) (*Client, error) {
	baseURL = strings.TrimSpace(baseURL)
	if baseURL == "" {
		return nil, errors.New("sdkgen: baseURL is required")
	}
	u, err := url.Parse(baseURL)
	if err != nil {
		return nil, fmt.Errorf("sdkgen: parse baseURL: %w", err)
	}
	if u.Scheme != "http" && u.Scheme != "https" {
		return nil, fmt.Errorf("sdkgen: baseURL scheme %q is not http or https", u.Scheme)
	}
	c := &Client{
		BaseURL:          baseURL,
		HTTPClient:       &http.Client{Timeout: DefaultTimeout},
		MaxResponseBytes: DefaultMaxResponseBytes,
	}
	for _, o := range opts {
		if o != nil {
			o(c)
		}
	}
	if c.HTTPClient == nil {
		c.HTTPClient = &http.Client{Timeout: DefaultTimeout}
	}
	if c.MaxResponseBytes <= 0 {
		c.MaxResponseBytes = DefaultMaxResponseBytes
	}
	return c, nil
}

// Response is the bounded result of a call. Body is kept for both success and
// non-2xx responses so callers can inspect the real payload.
type Response struct {
	StatusCode int
	Header     http.Header
	Body       []byte
}

// JSON decodes the response body into v.
func (r *Response) JSON(v any) error {
	if r == nil {
		return errors.New("sdkgen: nil response")
	}
	return json.Unmarshal(r.Body, v)
}

// APIError reports a non-2xx response without discarding its status, headers,
// or bounded body.
type APIError struct {
	StatusCode int
	Header     http.Header
	Body       []byte
}

func (e *APIError) Error() string {
	if e == nil {
		return "sdkgen: <nil> APIError"
	}
	return fmt.Sprintf("sdkgen: HTTP %d: %s", e.StatusCode, strings.TrimSpace(string(e.Body)))
}

// do builds and executes one request. It always closes the response body and
// bounds how much is read.
func (c *Client) do(ctx context.Context, method, opPath string, pathVals map[string]string, query url.Values, headerVals map[string]string, body []byte) (*Response, error) {
	if ctx == nil {
		ctx = context.Background()
	}
	endpoint, err := c.resolveURL(opPath, pathVals, query)
	if err != nil {
		return nil, err
	}
	var reader io.Reader
	if body != nil {
		reader = bytes.NewReader(body)
	}
	req, err := http.NewRequestWithContext(ctx, method, endpoint, reader)
	if err != nil {
		return nil, fmt.Errorf("sdkgen: build request: %w", err)
	}
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	if c.UserAgent != "" {
		req.Header.Set("User-Agent", c.UserAgent)
	}
	for name, value := range headerVals {
		if err := setHeader(req, name, value); err != nil {
			return nil, err
		}
	}
	if c.Auth != nil {
		if err := c.Auth(req); err != nil {
			return nil, fmt.Errorf("sdkgen: auth: %w", err)
		}
	}
	resp, err := c.HTTPClient.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	maxBytes := c.MaxResponseBytes
	if maxBytes <= 0 {
		maxBytes = DefaultMaxResponseBytes
	}
	data, err := io.ReadAll(io.LimitReader(resp.Body, maxBytes+1))
	if err != nil {
		return nil, fmt.Errorf("sdkgen: read response: %w", err)
	}
	if int64(len(data)) > maxBytes {
		return nil, fmt.Errorf("sdkgen: response body exceeds %d bytes", maxBytes)
	}
	out := &Response{StatusCode: resp.StatusCode, Header: resp.Header.Clone(), Body: data}
	if resp.StatusCode < 200 || resp.StatusCode > 299 {
		return out, &APIError{StatusCode: resp.StatusCode, Header: resp.Header.Clone(), Body: data}
	}
	return out, nil
}

// resolveURL joins the client base path and the operation template, substitutes
// escaped path values, and appends the encoded query.
func (c *Client) resolveURL(opPath string, pathVals map[string]string, query url.Values) (string, error) {
	base, err := url.Parse(c.BaseURL)
	if err != nil {
		return "", fmt.Errorf("sdkgen: parse baseURL: %w", err)
	}
	basePath := strings.TrimRight(base.EscapedPath(), "/")
	op := opPath
	if !strings.HasPrefix(op, "/") {
		op = "/" + op
	}
	for name, value := range pathVals {
		op = strings.ReplaceAll(op, "{"+name+"}", value)
	}
	if strings.Contains(op, "{") || strings.Contains(op, "}") {
		return "", fmt.Errorf("sdkgen: unresolved path template %q", opPath)
	}
	if query == nil {
		query = url.Values{}
	}
	if base.RawQuery != "" {
		baseQuery, err := url.ParseQuery(base.RawQuery)
		if err != nil {
			return "", fmt.Errorf("sdkgen: parse baseURL query: %w", err)
		}
		for k, vs := range baseQuery {
			for _, v := range vs {
				query.Add(k, v)
			}
		}
	}
	base.RawPath = basePath + op
	base.Path, err = url.PathUnescape(base.RawPath)
	if err != nil {
		return "", fmt.Errorf("sdkgen: invalid path %q: %w", base.RawPath, err)
	}
	base.RawQuery = query.Encode()
	base.Fragment = ""
	return base.String(), nil
}

// escapePathSegment percent-encodes one path parameter value.
func escapePathSegment(v string) string { return url.PathEscape(v) }

// setHeader sets one caller-supplied header, rejecting names and values that
// could inject a second header line.
func setHeader(req *http.Request, name, value string) error {
	if name == "" {
		return errors.New("sdkgen: empty header name")
	}
	if strings.ContainsAny(name, "\r\n:") {
		return fmt.Errorf("sdkgen: invalid header name %q", name)
	}
	if strings.ContainsAny(value, "\r\n") {
		return fmt.Errorf("sdkgen: invalid value for header %q", name)
	}
	req.Header.Set(name, value)
	return nil
}
`

func renderClient(opts Options, doc *specDoc, specDigest string) string {
	out := clientTemplate
	out = strings.ReplaceAll(out, "{{PKG}}", opts.PackageName)
	out = strings.ReplaceAll(out, "{{VERSION}}", doc.OpenAPI)
	out = strings.ReplaceAll(out, "{{DIGEST}}", specDigest)
	return out
}

// renderOperations renders every Input type, Validate method and client method.
func renderOperations(opts Options, ops []Operation) string {
	var b strings.Builder
	b.WriteString("// Code generated by GoRequest sdkgen; DO NOT EDIT.\n\n")
	b.WriteString("package " + opts.PackageName + "\n\n")

	usesJSON, usesStrconv, usesStrings := false, false, false
	for _, op := range ops {
		if op.Body() != nil {
			usesJSON = true
		}
		for _, p := range op.params() {
			if p.Kind != kindString {
				usesStrconv = true
			}
			if p.Array && (p.In == "path" || p.In == "header" || !p.Explode) {
				usesStrings = true
			}
		}
	}

	b.WriteString("import (\n")
	b.WriteString("\t\"context\"\n")
	if usesJSON {
		b.WriteString("\t\"encoding/json\"\n")
	}
	b.WriteString("\t\"errors\"\n")
	b.WriteString("\t\"net/url\"\n")
	if usesStrconv {
		b.WriteString("\t\"strconv\"\n")
	}
	if usesStrings {
		b.WriteString("\t\"strings\"\n")
	}
	b.WriteString(")\n\n")

	for _, op := range ops {
		renderOperation(&b, op)
	}
	return b.String()
}

// Operation.params and Operation.Body are helpers defined on the public type.
func (o Operation) params() []paramSpec { return o.paramsList }
func (o Operation) Body() *bodySpec     { return o.body }

func renderOperation(b *strings.Builder, op Operation) {
	params := op.params()
	rawNames := make([]string, len(params))
	for i, p := range params {
		rawNames[i] = p.Name
	}
	fields := assignFieldNames(rawNames)

	fmt.Fprintf(b, "// %sInput holds the parameters of %s %s.\n", op.GoName, op.Method, op.Path)
	fmt.Fprintf(b, "type %sInput struct {\n", op.GoName)
	for i, p := range params {
		req := "a required"
		if !p.Required {
			req = "an optional"
		}
		extra := ""
		if p.Array {
			extra = " (array)"
		}
		fmt.Fprintf(b, "\t// %s is %s %s parameter%s.\n", fields[i], req, p.In, extra)
		fmt.Fprintf(b, "\t%s %s\n", fields[i], fieldType(p))
	}
	if op.Body() != nil {
		req := "a required"
		if !op.Body().Required {
			req = "an optional"
		}
		fmt.Fprintf(b, "\t// Body is %s application/json request body.\n", req)
		b.WriteString("\tBody json.RawMessage\n")
	}
	b.WriteString("}\n\n")

	fmt.Fprintf(b, "// Validate reports missing required parameters.\n")
	fmt.Fprintf(b, "func (in *%sInput) Validate() error {\n", op.GoName)
	b.WriteString("\tif in == nil {\n")
	fmt.Fprintf(b, "\t\treturn errors.New(%q)\n", op.GoName+"Input is nil")
	b.WriteString("\t}\n")
	for i, p := range params {
		if !p.Required {
			continue
		}
		fmt.Fprintf(b, "\tif in.%s == nil {\n", fields[i])
		fmt.Fprintf(b, "\t\treturn errors.New(%q)\n", op.GoName+"Input."+fields[i]+" is required")
		b.WriteString("\t}\n")
	}
	if op.Body() != nil && op.Body().Required {
		b.WriteString("\tif in.Body == nil {\n")
		fmt.Fprintf(b, "\t\treturn errors.New(%q)\n", op.GoName+"Input.Body is required")
		b.WriteString("\t}\n")
	}
	b.WriteString("\treturn nil\n")
	b.WriteString("}\n\n")

	fmt.Fprintf(b, "// %s calls %s %s.\n", op.GoName, op.Method, op.Path)
	fmt.Fprintf(b, "func (c *Client) %s(ctx context.Context, in *%sInput) (*Response, error) {\n", op.GoName, op.GoName)
	b.WriteString("\tif in == nil {\n")
	fmt.Fprintf(b, "\t\tin = &%sInput{}\n", op.GoName)
	b.WriteString("\t}\n")
	b.WriteString("\tif err := in.Validate(); err != nil {\n")
	b.WriteString("\t\treturn nil, err\n")
	b.WriteString("\t}\n")
	b.WriteString("\tpathVals := map[string]string{}\n")
	b.WriteString("\tq := url.Values{}\n")
	b.WriteString("\theaders := map[string]string{}\n")

	for i, p := range params {
		field := "in." + fields[i]
		switch p.In {
		case "path":
			renderPathParam(b, p, field)
		case "query":
			renderQueryParam(b, p, field)
		case "header":
			renderHeaderParam(b, p, field)
		}
	}

	b.WriteString("\tvar body []byte\n")
	if op.Body() != nil {
		b.WriteString("\tif in.Body != nil {\n")
		b.WriteString("\t\tif !json.Valid(in.Body) {\n")
		fmt.Fprintf(b, "\t\t\treturn nil, errors.New(%q)\n", op.GoName+"Input.Body is not valid JSON")
		b.WriteString("\t\t}\n")
		b.WriteString("\t\tbody = []byte(in.Body)\n")
		b.WriteString("\t}\n")
	}
	fmt.Fprintf(b, "\treturn c.do(ctx, %q, %q, pathVals, q, headers, body)\n", op.Method, op.Path)
	b.WriteString("}\n\n")
}

func fieldType(p paramSpec) string {
	base := string(p.Kind)
	if p.Array {
		return "[]" + base
	}
	return "*" + base
}

func renderPathParam(b *strings.Builder, p paramSpec, field string) {
	if p.Array {
		fmt.Fprintf(b, "\tif %s != nil {\n", field)
		fmt.Fprintf(b, "\t\tvals := make([]string, len(%s))\n", field)
		fmt.Fprintf(b, "\t\tfor i, v := range %s {\n", field)
		fmt.Fprintf(b, "\t\t\tvals[i] = escapePathSegment(%s)\n", scalarFormat(p.Kind, "v"))
		b.WriteString("\t\t}\n")
		fmt.Fprintf(b, "\t\tpathVals[%q] = strings.Join(vals, \",\")\n", p.Name)
		b.WriteString("\t}\n")
		return
	}
	fmt.Fprintf(b, "\tif %s != nil {\n", field)
	fmt.Fprintf(b, "\t\tpathVals[%q] = escapePathSegment(%s)\n", p.Name, scalarFormat(p.Kind, "*"+field))
	b.WriteString("\t}\n")
}

func renderQueryParam(b *strings.Builder, p paramSpec, field string) {
	if p.Array {
		sep := ","
		switch p.Style {
		case "spacedelimited":
			sep = " "
		case "pipedelimited":
			sep = "|"
		}
		if p.Explode && (p.Style == "" || p.Style == "form") {
			fmt.Fprintf(b, "\tif %s != nil {\n", field)
			fmt.Fprintf(b, "\t\tfor _, v := range %s {\n", field)
			fmt.Fprintf(b, "\t\t\tq.Add(%q, %s)\n", p.Name, scalarFormat(p.Kind, "v"))
			b.WriteString("\t\t}\n")
			b.WriteString("\t}\n")
			return
		}
		fmt.Fprintf(b, "\tif %s != nil {\n", field)
		fmt.Fprintf(b, "\t\tvals := make([]string, len(%s))\n", field)
		fmt.Fprintf(b, "\t\tfor i, v := range %s {\n", field)
		fmt.Fprintf(b, "\t\t\tvals[i] = %s\n", scalarFormat(p.Kind, "v"))
		b.WriteString("\t\t}\n")
		fmt.Fprintf(b, "\t\tq.Set(%q, strings.Join(vals, %q))\n", p.Name, sep)
		b.WriteString("\t}\n")
		return
	}
	fmt.Fprintf(b, "\tif %s != nil {\n", field)
	fmt.Fprintf(b, "\t\tq.Set(%q, %s)\n", p.Name, scalarFormat(p.Kind, "*"+field))
	b.WriteString("\t}\n")
}

func renderHeaderParam(b *strings.Builder, p paramSpec, field string) {
	if p.Array {
		fmt.Fprintf(b, "\tif %s != nil {\n", field)
		fmt.Fprintf(b, "\t\tvals := make([]string, len(%s))\n", field)
		fmt.Fprintf(b, "\t\tfor i, v := range %s {\n", field)
		fmt.Fprintf(b, "\t\t\tvals[i] = %s\n", scalarFormat(p.Kind, "v"))
		b.WriteString("\t\t}\n")
		fmt.Fprintf(b, "\t\theaders[%q] = strings.Join(vals, \",\")\n", p.Name)
		b.WriteString("\t}\n")
		return
	}
	fmt.Fprintf(b, "\tif %s != nil {\n", field)
	fmt.Fprintf(b, "\t\theaders[%q] = %s\n", p.Name, scalarFormat(p.Kind, "*"+field))
	b.WriteString("\t}\n")
}

// scalarFormat renders a scalar value expression for a Go type.
func scalarFormat(kind paramKind, expr string) string {
	switch kind {
	case kindInt64:
		return "strconv.FormatInt(" + expr + ", 10)"
	case kindFloat64:
		return "strconv.FormatFloat(" + expr + ", 'g', -1, 64)"
	case kindBool:
		return "strconv.FormatBool(" + expr + ")"
	default:
		return expr
	}
}

// renderReadme writes the minimal, deterministic README. It never embeds
// server URLs, credentials, or examples from the project contract.
func renderReadme(opts Options, doc *specDoc, ops []Operation, unsupported []UnsupportedOperation, diags []Diagnostic) string {
	var b strings.Builder
	title := safeTitle(doc.Info.Title, opts.PackageName)
	fmt.Fprintf(&b, "# %s Go SDK\n\n", mdCell(title))
	fmt.Fprintf(&b, "Generated by GoRequest sdkgen (`%s`, template `%s`) from an OpenAPI `%s` contract.\n\n", GeneratorVersion, TemplateVersion, doc.OpenAPI)
	fmt.Fprintf(&b, "- Package: `%s`\n- Module: `%s`\n- Operations: %d\n\n", opts.PackageName, opts.ModulePath, len(ops))
	b.WriteString("This package uses only the Go standard library. Authentication is supplied by the caller through `Client.Auth`; no credentials, tokens, cookies, or secret values are embedded.\n\n")
	b.WriteString("## Usage\n\n")
	b.WriteString("```go\n")
	fmt.Fprintf(&b, "client, err := %s.NewClient(\"https://api.example.com\", %s.WithAuth(func(req *http.Request) error {\n", opts.PackageName, opts.PackageName)
	b.WriteString("\treq.Header.Set(\"Authorization\", \"Bearer \"+os.Getenv(\"API_TOKEN\"))\n\treturn nil\n}))\n")
	b.WriteString("if err != nil {\n\treturn err\n}\n")
	if len(ops) > 0 {
		first := ops[0]
		fmt.Fprintf(&b, "input := &%s.%sInput{ /* fill required parameters */ }\n", opts.PackageName, first.GoName)
		fmt.Fprintf(&b, "resp, err := client.%s(context.Background(), input)\n", first.GoName)
		b.WriteString("if err != nil {\n\treturn err\n}\n")
		b.WriteString("_ = resp\n")
	}
	b.WriteString("```\n\n")

	if len(ops) > 0 {
		b.WriteString("## Operations\n\n")
		b.WriteString("| Method | Path | Go method |\n| --- | --- | --- |\n")
		for _, op := range ops {
			fmt.Fprintf(&b, "| %s | `%s` | `%s` |\n", op.Method, mdCell(op.Path), op.GoName)
		}
		b.WriteString("\n")
	}

	if len(unsupported) > 0 {
		b.WriteString("## Not generated\n\n")
		for _, u := range unsupported {
			fmt.Fprintf(&b, "- `%s %s`: %s\n", u.Method, mdCell(u.Path), mdCell(u.Reason))
		}
		b.WriteString("\n")
	}
	if len(diags) > 0 {
		b.WriteString("## Diagnostics\n\n")
		for _, d := range diags {
			fmt.Fprintf(&b, "- [%s/%s] %s: %s\n", d.Severity, d.Code, mdCell(d.Location), mdCell(d.Message))
		}
		b.WriteString("\n")
	}

	b.WriteString("## Safety\n\n")
	b.WriteString("- Response bodies are bounded (default 8 MiB); non-2xx responses return `*APIError` with the real status, headers, and bounded body.\n")
	b.WriteString("- The generator never executes the generated code and never reads secrets, cookies, history, or tokens.\n")
	b.WriteString("- Re-running the generator only updates files listed in the ownership manifest whose digests still match; manual files are never overwritten or deleted.\n")
	return b.String()
}

func mdCell(s string) string {
	s = strings.ReplaceAll(s, "|", "\\|")
	s = strings.ReplaceAll(s, "\n", " ")
	return s
}

// safeTitle is a conservative defense-in-depth guard: the snapshot is expected
// to be redacted already, but a free-form title that still looks like a
// credential or a template placeholder falls back to the package name rather
// than leaking into the README.
func safeTitle(title, fallback string) string {
	t := strings.TrimSpace(title)
	if t == "" {
		return fallback
	}
	lower := strings.ToLower(t)
	for _, marker := range []string{"{{", "}}", "sk-", "bearer ", "basic ", "token=", "api_key=", "apikey=", "password="} {
		if strings.Contains(lower, marker) {
			return fallback
		}
	}
	return t
}
